#!/usr/bin/env bash
# Print the three most frequent client IPs, resolving equal counts by the
# order in which each address first occurs in the access log.
set -euo pipefail

if [[ ! -r access.log ]]; then
    printf 'top_talkers.sh: access.log is missing or unreadable\n' >&2
    exit 1
fi

awk '
{
    ip = $1
    if (!(ip in first_seen))
        first_seen[ip] = ++sequence
    ++count[ip]
}
END {
    # Select one address at a time so that the tie-breaking rule does not
    # depend on awk associative-array traversal order.
    for (place = 1; place <= 3; ++place) {
        best = ""
        for (ip in count) {
            if (ip in selected)
                continue
            if (best == "" || count[ip] > count[best] || \
                (count[ip] == count[best] && first_seen[ip] < first_seen[best]))
                best = ip
        }
        if (best == "")
            break
        print best
        selected[best] = 1
    }
}
' access.log
